"""Additional isolated expressions, derived from observed contracts, not gold SQL."""
def extend(add,CAT):
 def put(id,col,old,expr,why='恢复契约规定的这一列；其余SQL字节不动。'):
  add(id,col,old+' '+col,expr+' '+col,why)
 id='impl-001_lever__hiring_manager_scorecard'
 cand='FROM staging.stg_lever__application aa LEFT JOIN marts.lever__candidate_experience_insights ce ON aa.opportunity_id=ce.opportunity_id WHERE aa.posting_hiring_manager_user_id=m.hiring_manager_id'
 put(id,'avg_candidate_experience_score','0.0',f'(SELECT coalesce(avg(ce.overall_candidate_experience_score),0) {cand})')
 inter='FROM staging.stg_lever__application aa LEFT JOIN staging.stg_lever__interview ii ON aa.opportunity_id=ii.opportunity_id LEFT JOIN staging.stg_lever__interviewer_user iu ON ii.interview_id=iu.interview_id LEFT JOIN staging.stg_lever__interview_feedback fb ON ii.interview_id=fb.interview_id WHERE aa.posting_hiring_manager_user_id=m.hiring_manager_id'
 for col,old,expr in [('interview_success_rate','0.0','coalesce(round(count(DISTINCT ii.interview_id) FILTER(WHERE ii.canceled_at IS NULL)*100.0/nullif(count(DISTINCT ii.interview_id),0),2),0)'),('feedback_completion_rate_managed','0.0','CASE WHEN count(DISTINCT fb.feedback_form_id)>0 THEN 100.0 ELSE 0.0 END::DOUBLE'),('interviewer_network_size','0::BIGINT','count(DISTINCT iu.user_id)'),('total_interviews_coordinated','0::BIGINT','count(DISTINCT ii.interview_id)')]:put(id,col,old,f'(SELECT {expr} {inter})')
 put(id,'high_efficiency_postings','0::BIGINT',"(SELECT count(DISTINCT aa.posting_id) FILTER(WHERE ff.hiring_efficiency_grade='High Efficiency (≥10%)') FROM staging.stg_lever__application aa LEFT JOIN intermediate.int_lever__hiring_funnel_metrics ff ON aa.posting_id=ff.posting_id WHERE aa.posting_hiring_manager_user_id=m.hiring_manager_id)")
 put(id,'overall_performance_score','NULL::DOUBLE','least(100,greatest(0,round(.25*requisition_fill_rate+.25*high_performing_posting_rate+.25*candidate_hire_rate+.15*interview_success_rate+CASE WHEN avg_total_days_to_hire<=45 THEN 10 ELSE greatest(0,10-(avg_total_days_to_hire-45)*.2) END,0)))')
 put(id,'performance_tier',"'New/Limited Experience'","CASE WHEN overall_performance_score>=80 THEN 'Outstanding Hiring Manager' WHEN overall_performance_score>=65 THEN 'Effective Hiring Manager' WHEN overall_performance_score>=50 THEN 'Competent Hiring Manager' WHEN coalesce(p.total_candidates_managed,0)>=5 THEN 'Developing Hiring Manager' ELSE 'New/Limited Experience' END")
 put(id,'hiring_specialization',"'Generalist'","CASE WHEN high_performing_posting_rate>=70 THEN 'Job Marketing Expert' WHEN avg_candidate_experience_score>=4 THEN 'Candidate Experience Specialist' WHEN feedback_completion_rate_managed>=85 THEN 'Process Coordinator' WHEN avg_total_days_to_hire<=30 THEN 'Fast Decision Maker' WHEN coalesce(r.teams_supported,0)>=3 THEN 'Multi-Team Recruiter' ELSE 'Generalist' END")
 # Exact recommendation wording is not fixed; inspect separate diagnostic, do not invent it as contract text.
 id='impl-002_int_pendo__product_health_metrics'
 visitor='(SELECT account_id,visitor_id,count(DISTINCT CAST(occurred_at AS DATE)) count_active_days,sum(num_events) sum_events,max(CAST(occurred_at AS DATE)) last_event_on FROM staging.stg_pendo__event GROUP BY 1,2)'
 ret=f"(SELECT account_id,count(DISTINCT visitor_id) total_users,avg(count_active_days) avg_active_days_per_user,avg(sum_events) avg_lifetime_events,count(*) FILTER(WHERE count_active_days>=20)::FLOAT/count(DISTINCT visitor_id) highly_active_user_rate FROM {visitor} GROUP BY 1)"
 add(id,'retention_join','FROM f FULL OUTER JOIN e ON f.account_id=e.account_id AND f.app_id=e.app_id',f'FROM (SELECT coalesce(f.account_id,urm.account_id) account_id,f.* EXCLUDE(account_id) FROM f FULL OUTER JOIN {ret} urm ON f.account_id=urm.account_id) f FULL OUTER JOIN e ON f.account_id=e.account_id AND f.app_id=e.app_id','契约要求在feature与engagement之间full outer join账户级retention；只改这一处来源连接。')
 for n in [7,30,90]:
  put(id,f'retention_{n}d','NULL::FLOAT',f"(SELECT count(*) FILTER(WHERE vv.last_event_on>=current_date-INTERVAL {n} DAY)::FLOAT/count(DISTINCT vv.visitor_id) FROM {visitor} vv WHERE vv.account_id=f.account_id GROUP BY vv.account_id)")
 for col in ['avg_active_days_per_user','avg_lifetime_events','highly_active_user_rate']:
  put(id,col,'NULL::FLOAT' if col=='highly_active_user_rate' else 'NULL::DOUBLE',f'(SELECT rr.{col} FROM {ret} rr WHERE rr.account_id=f.account_id)')
 put(id,'feature_depth_adoption_rate','NULL::FLOAT',"(SELECT count(DISTINCT feature_id) FILTER(WHERE num_events>=10)::FLOAT/nullif(count(DISTINCT feature_id),0) FROM staging.stg_pendo__feature_event ff WHERE ff.account_id=f.account_id AND ff.app_id=f.app_id)")
 put(id,'avg_features_per_user','NULL::FLOAT','f.features_used::FLOAT/nullif(f.active_feature_users,0)')
 put(id,'deep_engagement_session_rate','NULL::FLOAT',"(SELECT count(*) FILTER(WHERE num_minutes>=10 OR num_events>=20)::FLOAT/count(*) FROM staging.stg_pendo__event ee WHERE ee.account_id=e.account_id AND ee.app_id=e.app_id)")
 put(id,'health_grade',"'Critical'","CASE WHEN overall_health_score>=80 THEN 'Excellent' WHEN overall_health_score>=60 THEN 'Good' WHEN overall_health_score>=40 THEN 'Fair' WHEN overall_health_score>=20 THEN 'Poor' ELSE 'Critical' END")
 put(id,'risk_level',"'High Risk'","CASE WHEN overall_health_score<30 THEN 'High Risk' WHEN (overall_health_score<50 AND coalesce(NULL::FLOAT,0)<.4) OR coalesce(NULL::FLOAT,0)<-.2 THEN 'Medium Risk' ELSE 'Low' END")
 # risk_level references later select fields: use explicit original NULLs to preserve all other placeholders.
 planold="CASE WHEN overall_health_score<30 THEN 'High Risk' WHEN (overall_health_score<50 AND coalesce(NULL::FLOAT,0)<.4) OR coalesce(NULL::FLOAT,0)<-.2 THEN 'Medium Risk' ELSE 'Low' END"
 # Restored score component alone can be tested without borrowing gold output.
 add(id,'health_score_complete','0::FLOAT overall_health_score',"least(100,(coalesce(NULL::FLOAT,0)+1)*12.5+coalesce(f.features_used::FLOAT/nullif(f.total_features_available,0),0)*25+coalesce(NULL::FLOAT,0)*25+coalesce(NULL::FLOAT,0)*12.5+coalesce(CASE WHEN e.unique_users>0 THEN .2 ELSE NULL END,0)*12.5)::FLOAT overall_health_score",'恢复完整评分公式，仍保留其他列原先NULL/默认输入；只改score表达式。')
 id='impl-002_pendo__executive_dashboard_metrics'
 accounts="(SELECT ah.account_id,max(ph.overall_health_score) health,max(ph.net_promoter_score) nps,max(ph.feature_adoption_rate) adoption,max(ph.retention_30d) retention FROM staging.stg_pendo__account_history ah LEFT JOIN intermediate.int_pendo__product_health_metrics ph USING(account_id) GROUP BY ah.account_id)"
 for col,field in [('avg_platform_health_score','health'),('avg_retention_rate','retention')]:put(id,col,'NULL::DOUBLE',f'(SELECT avg({field}) FROM {accounts})')
 for col,pred in [('medium_risk_accounts','health<50'),('low_risk_accounts','(health>=50 OR health IS NULL) AND (nps>=0 OR nps IS NULL)')]:put(id,col,'0::BIGINT',f'(SELECT count(*) FILTER(WHERE {pred}) FROM {accounts})')
 put(id,'overall_business_health_score','NULL::DOUBLE','least(100,.25*avg_platform_health_score+.15*((avg_platform_nps+1)*50)+.15*avg_feature_adoption*100+.15*avg_retention_rate*100+.10*conversion_rate*100+.20*CASE WHEN user_growth_rate_7d>=0 THEN 50+100*user_growth_rate_7d ELSE 50*(1+user_growth_rate_7d) END)')
 put(id,'primary_alert_status',"'All Systems Normal'","CASE WHEN high_risk_accounts>.2*a.total_accounts THEN 'Account Risk Alert' WHEN avg_platform_nps<-.2 THEN 'Customer Satisfaction Alert' WHEN user_growth_rate_7d<-.1 THEN 'Growth Decline Alert' WHEN avg_retention_rate<.6 THEN 'Retention Alert' WHEN customers_needing_attention>.25*platform_total_users THEN 'Customer Health Alert' ELSE 'All Systems Normal' END")
